# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">02</span><span class="sec-icon">🌊</span><h2>Structured Streaming in one example</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">PYTHON</span><button class="copy" type="button">copy</button></div><pre><span style="color: #FF7B72">from</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">pyspark.sql</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">import</span> <span style="color: #E6EDF3">functions</span> <span style="color: #FF7B72">as</span> <span style="color: #E6EDF3">F</span>
# MAGIC <span></span>
# MAGIC <span style="color: #E6EDF3">events</span> <span style="color: #FF7B72; font-weight: bold">=</span> <span style="color: #E6EDF3">(spark</span><span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">readStream</span>                       <span style="color: #8B949E; font-style: italic"># source: Delta table, Auto Loader, Kafka…</span>
# MAGIC           <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">table(</span><span style="color: #A5D6FF">"main.bronze.device_events"</span><span style="color: #E6EDF3">))</span>
# MAGIC <span></span>
# MAGIC <span style="color: #E6EDF3">per_window</span> <span style="color: #FF7B72; font-weight: bold">=</span> <span style="color: #E6EDF3">(events</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">withWatermark(</span><span style="color: #A5D6FF">"event_ts"</span><span style="color: #E6EDF3">,</span> <span style="color: #A5D6FF">"10 minutes"</span><span style="color: #E6EDF3">)</span>     <span style="color: #8B949E; font-style: italic"># accept data up to 10 min late, then drop state</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">groupBy(F</span><span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">window(</span><span style="color: #A5D6FF">"event_ts"</span><span style="color: #E6EDF3">,</span> <span style="color: #A5D6FF">"5 minutes"</span><span style="color: #E6EDF3">),</span> <span style="color: #A5D6FF">"device_id"</span><span style="color: #E6EDF3">)</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">agg(F</span><span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">avg(</span><span style="color: #A5D6FF">"temp"</span><span style="color: #E6EDF3">)</span><span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">alias(</span><span style="color: #A5D6FF">"avg_temp"</span><span style="color: #E6EDF3">)))</span>
# MAGIC <span></span>
# MAGIC <span style="color: #E6EDF3">(per_window</span><span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">writeStream</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">outputMode(</span><span style="color: #A5D6FF">"append"</span><span style="color: #E6EDF3">)</span>                        <span style="color: #8B949E; font-style: italic"># emit each window once, when it is final</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">option(</span><span style="color: #A5D6FF">"checkpointLocation"</span><span style="color: #E6EDF3">,</span> <span style="color: #A5D6FF">"/Volumes/main/chk/device_5min"</span><span style="color: #E6EDF3">)</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">trigger(availableNow</span><span style="color: #FF7B72; font-weight: bold">=</span><span style="color: #79C0FF">True</span><span style="color: #E6EDF3">)</span>                  <span style="color: #8B949E; font-style: italic"># process what's there, then stop</span>
# MAGIC     <span style="color: #FF7B72; font-weight: bold">.</span><span style="color: #E6EDF3">toTable(</span><span style="color: #A5D6FF">"main.silver.device_5min"</span><span style="color: #E6EDF3">))</span></pre></div>
# MAGIC <div class="tbl"><table>
# MAGIC <thead>
# MAGIC <tr>
# MAGIC <th>Concept</th>
# MAGIC <th>Options</th>
# MAGIC </tr>
# MAGIC </thead>
# MAGIC <tbody>
# MAGIC <tr>
# MAGIC <td><strong>Trigger</strong></td>
# MAGIC <td>default / <code>processingTime="1 minute"</code> (continuous micro-batches) · <strong><code>availableNow=True</code></strong> (incremental batch, then stop) · real-time mode (very low latency)</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><strong>Output mode</strong></td>
# MAGIC <td><strong>Append</strong>: only new, final rows (aggregations need a watermark) · <strong>Update</strong>: changed rows (use with <code>foreachBatch</code> + <code>MERGE</code>) · <strong>Complete</strong>: whole result each trigger (keeps all state)</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><strong>Checkpoint</strong></td>
# MAGIC <td>Source offsets + committed batches + state. <strong>One per query.</strong> Never share it or delete it</td>
# MAGIC </tr>
# MAGIC </tbody>
# MAGIC </table></div>
# MAGIC </div>

