# MAGIC <div class="sec-head"><span class="sec-num">05</span><span class="sec-icon">🌊</span><h2>Streaming in declarative pipelines</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">SQL</span><button class="copy" type="button">copy</button></div><pre><span style="color: #8B949E; font-style: italic">-- Bronze from Kafka: decode the value, keep metadata</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">REFRESH</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAMING</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">events_bronze</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span>
