# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_kafka(bootstrapServers</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'&#36;{kafka_servers}'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">subscribe</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'events'</span><span style="color: #E6EDF3">);</span>
